import re
import math
import json

PATH = """M 0.0,-10.58113 L 0.0,-11.53256 M 9.9124,-6.76346 L 10.59842,-5.75805 M 7.23506,-4.93665 L 9.9124,-6.76346 M 9.97176,-0.75094 L 7.8029,-0.58761 M -7.46321,-14.83889 L -8.84366,-17.58359 M 10.69153,4.81097 L 5.63621,8.26033 M 9.9124,-6.76346 L 0.0,0.0 M -9.88505,-19.65415 L -9.88505,-23.17735 M 0.0,-11.53256 L 9.9124,-6.76346 M 8.93931,17.77377 L 10.49708,20.87103 M 0.0,-11.53256 L 0.0,-8.88007 M 0.0,0.0 L 7.5579,15.02714 M 6.69042,-4.56503 L 7.23506,-4.93665 M 10.59842,-5.75805 L 11.54577,-4.36962 M 0.0,0.0 L 6.24481,-4.26098 M 0.0,-3.90723 L 0.0,0.0 M 7.27515,-0.54787 L 7.07995,-0.53317 M -5.79955,-11.5311 L -7.46321,-14.83889 M 7.8029,-0.58761 L 7.27515,-0.54787 M 11.54577,-4.36962 L 12.04478,-3.63828 L 12.27961,-3.29412 M 7.5579,15.02714 L 8.93931,17.77377 M 0.0,0.0 L -4.94252,-9.82708 M 7.07995,-0.53317 L 5.52236,-0.41587 M 15.54861,1.49687 L 10.69153,4.81097 M 5.52236,-0.41587 L 0.0,0.0 M 12.27961,-3.29412 L 15.54861,1.49687 M -9.88505,-23.17735 L -9.88505,-25.07446 M 6.24481,-4.26098 L 6.69042,-4.56503 M 0.0,0.0 L 0.0,-7.72682 M 0.0,-8.88007 L 0.0,-3.90723 M 0.0,-7.72682 L 0.0,-10.58113 M -9.88505,-25.07446 L -9.88505,-27.55604 M -4.94252,-9.82708 L -5.79955,-11.5311 M 5.63621,8.26033 L 9.97176,-0.75094 M -8.84366,-17.58359 L -9.88505,-19.65415 M -9.88505,-31.18672 L 0.0,-11.53256 M -9.88505,-27.55604 L -9.88505,-28.61957 L -9.88505,-31.18672"""

EPS = 0.00003

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def norm(a):
    return math.hypot(*a)

def on_segment(p, a, b):
    v, w = sub(b, a), sub(p, a)
    length = norm(v)
    return (abs(cross(v, w)) <= EPS * length
            and -EPS * length <= dot(w, v) <= dot(v, v) + EPS * length)

def parallel(a, b):
    return abs(cross(a, b)) <= EPS * (norm(a) + norm(b))

def perpendicular(a, b):
    return abs(dot(a, b)) <= EPS * (norm(a) + norm(b))

def same_length(a, b):
    return abs(norm(a) - norm(b)) <= 2 * EPS

segments = []
current = None
for command, x, y in re.findall(
        r"([ML])\s*([-+]?\d+(?:\.\d+)?),([-+]?\d+(?:\.\d+)?)", PATH):
    point = (float(x), float(y))
    if command == "L":
        segments.append((current, point))
    current = point

points = []
def point_id(p):
    for i, q in enumerate(points):
        if norm(sub(p, q)) <= EPS:
            return i
    points.append(p)
    return len(points) - 1

for a, b in segments:
    point_id(a)
    point_id(b)

# Add every proper intersection. Endpoint-on-segment and overlapping
# collinear segments are handled by the subsequent subdivision.
for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for c, d in segments[i + 1:]:
        s = sub(d, c)
        den = cross(r, s)
        if abs(den) <= 1e-12:
            continue
        t = cross(sub(c, a), s) / den
        u = cross(sub(c, a), r) / den
        if 0 < t < 1 and 0 < u < 1:
            point_id((a[0] + t * r[0], a[1] + t * r[1]))

graph = {i: set() for i in range(len(points))}
for a, b in segments:
    v = sub(b, a)
    ids = [i for i, p in enumerate(points) if on_segment(p, a, b)]
    ids.sort(key=lambda i: dot(sub(points[i], a), v))
    for u, w in zip(ids, ids[1:]):
        if u != w:
            graph[u].add(w)
            graph[w].add(u)

# Remove edges belonging to no cycle; merge collinear subdivision vertices.
changed = True
while changed:
    changed = False
    for u in list(graph):
        neighbours = graph[u]
        if len(neighbours) <= 1:
            for v in neighbours:
                graph[v].discard(u)
            del graph[u]
            changed = True
        elif len(neighbours) == 2:
            v, w = tuple(neighbours)
            if on_segment(points[u], points[v], points[w]):
                graph[v].discard(u)
                graph[w].discard(u)
                graph[v].add(w)
                graph[w].add(v)
                del graph[u]
                changed = True

def inside(p, polygon):
    if any(on_segment(p, a, b)
           for a, b in zip(polygon, polygon[1:] + polygon[:1])):
        return False
    result = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if x > p[0]:
                result = not result
    return result

cycles = set()
def visit(start, path, used):
    u = path[-1]
    for v in graph[u]:
        if v == start and len(path) >= 3:
            forward = tuple(path)
            backward = (start,) + tuple(reversed(path[1:]))
            cycles.add(min(forward, backward))
        elif v > start and v not in used:
            visit(start, path + [v], used | {v})

if len(graph) > 30:
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": "Enumeration exceeds the supported bound."}))
else:
    for start in sorted(graph):
        visit(start, [start], {start})

    edges = [(u, v) for u in graph for v in graph[u] if u < v]
    found = {}
    for cycle in sorted(cycles):
        polygon = [points[u] for u in cycle]
        n = len(polygon)
        vectors = [sub(polygon[(i + 1) % n], polygon[i]) for i in range(n)]
        turns = [cross(vectors[i], vectors[(i + 1) % n]) for i in range(n)]
        convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)

        # An internal drawn chord disqualifies the no-diagonals categories.
        if n >= 4 and any(
            inside(((points[u][0] + points[v][0]) / 2,
                    (points[u][1] + points[v][1]) / 2), polygon)
            for u, v in edges
        ):
            continue

        kinds = []
        if n == 3:
            right = any(perpendicular(vectors[i], vectors[(i + 1) % n])
                        for i in range(n))
            kinds = [4 if right else 3]
        elif n == 4 and convex:
            pairs = [parallel(vectors[0], vectors[2]),
                     parallel(vectors[1], vectors[3])]
            if all(pairs):
                rectangle = all(perpendicular(vectors[i], vectors[(i + 1) % n])
                                for i in range(n))
                square = rectangle and all(same_length(vectors[0], v)
                                           for v in vectors[1:])
                kinds = [2 if square else 1 if rectangle else 5]
            elif sum(pairs) == 1:
                kinds = [6]
        elif n in (5, 6):
            regular = (convex
                       and all(same_length(vectors[0], v) for v in vectors[1:])
                       and all(abs(math.atan2(turns[i],
                                              dot(vectors[i], vectors[(i + 1) % n]))
                                   - math.atan2(turns[0],
                                                dot(vectors[0], vectors[1]))) < 0.00003
                               for i in range(1, n)))
            if n == 5:
                kinds = [9 if regular else 7 if convex else 8]
            elif regular:
                kinds = [10]
        for kind in kinds:
            found.setdefault(kind, polygon)

    options = {
        "A": {8, 10}, "B": {3, 5}, "C": {8, 6}, "D": {3, 5, 8},
        "E": {6, 7}, "F": {5, 8}, "G": {3, 5, 4}, "H": {8, 1},
        "I": {5, 8, 6}, "J": {3, 7}, "K": {8, 2}, "L": {9},
        "M": {3}, "N": {3, 6, 7, 10}, "P": {8, 4}
    }
    matching = [letter for letter, kinds in options.items() if kinds == set(found)]
    answer = matching[0] if len(matching) == 1 else "O"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "shape_numbers": sorted(found),
            "vertices": {str(k): found[k] for k in sorted(found)},
            "cycles_enumerated": len(cycles)
        }
    }, separators=(",", ":")))
